CREATE TABLE reveal_tokens (
    token_hash      TEXT     NOT NULL PRIMARY KEY,
    note_id    TEXT     NOT NULL,
    expires_at DATETIME NOT NULL,
    used_at    DATETIME
);
CREATE TABLE users (
    id            TEXT     NOT NULL PRIMARY KEY,
    username      TEXT     NOT NULL UNIQUE,
    totp_secret   TEXT     NOT NULL,
    password_hash TEXT     NOT NULL DEFAULT '',
    kdf_salt      TEXT     NOT NULL DEFAULT '',
    is_admin          INTEGER  NOT NULL DEFAULT 0,
    last_totp_counter INTEGER  NOT NULL DEFAULT 0,
    created_at        DATETIME NOT NULL DEFAULT (datetime('now')),
    last_login_at     DATETIME
);
CREATE TABLE invites (
    token_hash      TEXT     NOT NULL PRIMARY KEY,
    created_by TEXT     NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    expires_at DATETIME NOT NULL,
    used_at    DATETIME,
    used_by    TEXT
);
CREATE TABLE sessions (
    session_hash TEXT     NOT NULL PRIMARY KEY,
    user_id    TEXT     NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    created_at DATETIME NOT NULL DEFAULT (datetime('now')),
    expires_at DATETIME NOT NULL,
    user_agent TEXT     NOT NULL DEFAULT '',
    ip         TEXT     NOT NULL DEFAULT ''
);
CREATE TABLE api_tokens (
    user_id      TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    token_hash   TEXT NOT NULL PRIMARY KEY,
    created_at   DATETIME NOT NULL DEFAULT (datetime('now')),
    expires_at   DATETIME,
    last_used_at DATETIME
, issued_by TEXT REFERENCES api_tokens(token_hash) ON DELETE CASCADE);
CREATE TABLE links (
    id               TEXT     NOT NULL PRIMARY KEY,
    target_url       TEXT     NOT NULL,
    privacy          TEXT     NOT NULL DEFAULT 'public',
    edit_code        TEXT     NOT NULL DEFAULT '',
    views            INTEGER  NOT NULL DEFAULT 0,
    burn_after_click INTEGER  NOT NULL DEFAULT 0,
    expires_at       DATETIME,
    owner_id         TEXT REFERENCES users(id) ON DELETE SET NULL,
    created_at       DATETIME NOT NULL DEFAULT (datetime('now'))
, direct_redirect INTEGER);
